// The one AuthorityBasis field order, reused by owner segments and projection.
#pragma once
#include "authority_basis.hpp"
#include <type_traits>
#include "resident/checkpoint/codec_visitor.hpp"
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
namespace hanmo::resident::authority_basis_codec_fields {
template<class C> Status source(C& c,SourceRef& r){c.field("domain",r.domain);c.field("kind",r.kind);return c.field("id",r.id);}
template<class C> Status id(C& c,const char* name,std::optional<StableId>& value){return c.optional(name,value,[](C& v,StableId& s){return v.field("value",s);});}
template<class C> Status catalog(C& c,CatalogIdentity& x){c.field("content_id",x.content_id);c.field("content_version",x.content_version);c.field("content_digest",x.content_digest);c.field("ruleset_id",x.ruleset_id);c.field("schema_sha256",x.schema_sha256);id(c,"pack_set_digest",x.pack_set_digest);c.sequence("module_versions",x.module_versions,[](C& v,auto& module){v.field("name",module.first);return v.field("version",module.second);});return c.field("artifact_sha256",x.artifact_sha256);}
template<class C> Status world(C& c,WorldIdentity& value){
 // This exact owner has only inline WorldId bytes and three Integer fields.
 // Its enclosing row owns those bytes; hex is a wire temporary, not retained
 // storage. No unknown-type zero-retention fallback is introduced here.
 if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)(void)0;
 StableId hex;if(!c.reading()){constexpr char digits[]="0123456789abcdef";for(auto byte:value.world_id){hex.push_back(digits[byte>>4]);hex.push_back(digits[byte&15]);}}c.field("world_id",hex);if(hex.size()!=value.world_id.size()*2)return c.reject("InvalidAuthorityWorldId");if(c.reading())for(std::size_t n=0;n<value.world_id.size();++n){auto digit=[](char ch){return ch>='0'&&ch<='9'?ch-'0':ch>='a'&&ch<='f'?ch-'a'+10:-1;};const auto hi=digit(hex[n*2]),lo=digit(hex[n*2+1]);if(hi<0||lo<0)return c.reject("InvalidAuthorityWorldId");value.world_id[n]=std::uint8_t(hi*16+lo);}c.field("execution_epoch",value.execution_epoch);c.field("revision",value.revision);return c.field("tick",value.tick);}
template<class C> Status at(C& c,ActorFoundationAt& value){Integer tag=static_cast<Integer>(value.kind);c.field("tag",tag);if(tag<0||tag>1)return c.reject("InvalidAuthorityAt");if(c.reading())value.kind=static_cast<ActorFoundationAt::Kind>(tag);if(tag==0)return c.field("legacy_tick",value.legacy_tick);if constexpr(std::is_same_v<std::decay_t<C>,CodecVisitor>)(void)0;EncodedWorldMoment encoded;if(!c.reading()){auto out=encode_world_moment(value.exact_moment);if(!out.ok)return {false,{},out.error};encoded=std::move(out.value);}c.field("half_day_tick",encoded.half_day_tick);c.field("numerator",encoded.sub_half_day.numerator);c.field("denominator",encoded.sub_half_day.denominator);if(c.reading()&&c.status().ok){auto out=decode_world_moment(encoded);if(!out.ok)return {false,{},out.error};value.exact_moment=std::move(out.value);}return c.status();}
template<class C> Status office_source(C& c,OfficeAuthoritySource& value){Integer tag=Integer(value.index());c.field("tag",tag);if(tag<0||tag>1)return c.reject("InvalidOfficeAuthoritySource");if(!c.status().ok)return c.status();if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<AuthoredOfficeAuthoritySource>(c).ok)return c.status();value=AuthoredOfficeAuthoritySource{};}else{if(!prepare_checkpoint_default_values<OfficeChangedAuthoritySource>(c).ok)return c.status();value=OfficeChangedAuthoritySource{};}}if(tag==0){auto& row=std::get<AuthoredOfficeAuthoritySource>(value);c.object("catalog_identity",[&](C& v){return catalog(v,row.catalog_identity);});c.field("office_id",row.office_id);return c.field("initial_epoch",row.initial_epoch);}return c.field("fact_id",std::get<OfficeChangedAuthoritySource>(value).fact_id);}
template<class C> Status grant_source(C& c,GrantAuthoritySource& value){Integer tag=Integer(value.index());c.field("tag",tag);if(tag<0||tag>1)return c.reject("InvalidGrantAuthoritySource");if(!c.status().ok)return c.status();if(c.reading()){if(tag==0){if(!prepare_checkpoint_default_values<AuthoredGrantAuthoritySource>(c).ok)return c.status();value=AuthoredGrantAuthoritySource{};}else{if(!prepare_checkpoint_default_values<GrantRevisionAuthoritySource>(c).ok)return c.status();value=GrantRevisionAuthoritySource{};}}if(tag==0){auto& row=std::get<AuthoredGrantAuthoritySource>(value);c.object("catalog_identity",[&](C& v){return catalog(v,row.catalog_identity);});return c.field("grant_id",row.grant_id);}auto& row=std::get<GrantRevisionAuthoritySource>(value);c.field("fact_id",row.fact_id);c.field("grant_id",row.grant_id);return c.field("revision",row.revision);}
template<class C> Status amount_component(C& c,AuthorityAmountComponent& value){StableId kind=std::holds_alternative<MoneyAuthorityAmount>(value)?"money":"item_quantity";c.field("kind",kind);if(kind!="money"&&kind!="item_quantity")return c.reject("InvalidAuthorityAmountKind");if(!c.status().ok)return c.status();if(c.reading()){if(kind=="money"){if(!prepare_checkpoint_default_values<MoneyAuthorityAmount>(c).ok)return c.status();value=MoneyAuthorityAmount{};}else{if(!prepare_checkpoint_default_values<ItemAuthorityAmount>(c).ok)return c.status();value=ItemAuthorityAmount{};}}
    if(kind=="money"){auto& x=std::get<MoneyAuthorityAmount>(value);c.field("currency_id",x.currency_id);c.sequence("wallet_ids",x.wallet_ids,[](C& v,StableId& s){return v.field("item",s);});c.field("amount",x.amount);if(x.currency_id!="qian"||x.amount<0||x.wallet_ids.empty()||x.wallet_ids.size()>128)return c.reject("InvalidAuthorityMoneyAmount");}
    else {auto& x=std::get<ItemAuthorityAmount>(value);c.field("item_id",x.item_id);c.sequence("inventory_ids",x.inventory_ids,[](C& v,StableId& s){return v.field("item",s);});c.field("amount",x.amount);if(x.item_id.empty()||x.amount<0||x.inventory_ids.empty()||x.inventory_ids.size()>128)return c.reject("InvalidAuthorityItemAmount");}return c.status();}
template<class C> Status basis(C& c,AuthorityBasis& value){c.object("source_identity",[&](C& v){return world(v,value.source_identity);});c.field("actor_id",value.actor_id);c.field("organization_id",value.organization_id);c.field("office_id",value.office_id);c.field("office_epoch",value.office_epoch);c.field("grant_id",value.grant_id);c.field("grant_revision",value.grant_revision);id(c,"delegation_id",value.delegation_id);c.optional("parent_grant_ref",value.parent_grant_ref,[](C& v,ParentGrantRef& row){v.field("grant_id",row.grant_id);v.field("grant_revision",row.grant_revision);return v.object("authority_source",[&](C& w){return grant_source(w,row.authority_source);});});c.field("command_kind",value.command_kind);c.object("scope",[&](C& v){Integer kind=static_cast<Integer>(value.scope.kind);v.field("kind",kind);if(kind<0||kind>4)return v.reject("InvalidAuthorityScope");if(v.reading())value.scope.kind=static_cast<ScopeRef::Kind>(kind);return v.field("id",value.scope.id);});c.sequence("resources",value.resources,[](C& v,ResourceKey& row){Integer kind=row.kind==ResourceKey::Kind::wallet?0:row.kind==ResourceKey::Kind::inventory?1:-1;v.field("kind",kind);if(kind<0||kind>1)return v.reject("InvalidAuthorityResourceKind");if(v.reading())row.kind=kind==0?ResourceKey::Kind::wallet:ResourceKey::Kind::inventory;return v.field("id",row.id);});c.field("amount",value.amount);c.field("amount_limit",value.amount_limit);c.sequence("amount_components",value.amount_components,[](C& v,AuthorityAmountComponent& row){return amount_component(v,row);});c.optional("budget_ref",value.budget_ref,[](C& v,BudgetAuthorizationRef& row){v.field("authorization_id",row.authorization_id);v.field("authorization_revision",row.authorization_revision);return v.object("approval_source",[&](C& w){return source(w,row.approval_source);});});c.field("valid_from",value.valid_from);c.optional("valid_until",value.valid_until,[](C& v,Integer& until){return v.field("value",until);});c.field("continuity_policy_id",value.continuity_policy_id);c.field("issued_tick",value.issued_tick);c.field("issued_fact_sequence",value.issued_fact_sequence);c.object("issued_at",[&](C& v){return at(v,value.issued_at);});c.object("issued_source",[&](C& v){return source(v,value.issued_source);});c.object("office_source",[&](C& v){return office_source(v,value.office_source);});c.object("grant_source",[&](C& v){return grant_source(v,value.grant_source);});if(!c.status().ok)return c.status();if(value.actor_id.empty()||value.organization_id.empty()||value.office_id.empty()||value.grant_id.empty()||value.office_epoch<0||value.grant_revision<0||value.command_kind.empty()||value.amount<0||value.amount_limit<value.amount||value.valid_from<0||(value.valid_until&&*value.valid_until<value.valid_from)||value.issued_tick<0||value.issued_fact_sequence<1||value.resources.size()>128||value.amount_components.size()>128||(!value.amount_components.empty()&&value.amount!=0)||(value.budget_ref&&(value.budget_ref->authorization_id.empty()||value.budget_ref->authorization_revision<1)))return c.reject("InvalidAuthorityBasisShape");return c.status();}

}
